import React, { useEffect, useState } from "react";
import { getNotices, getStudy } from "../services/api";

const AdminDashboard = () => {
  const [notices, setNotices] = useState([]);
  const [study, setStudy] = useState([]);

  // 🔥 FETCH DATA FROM BACKEND
  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const noticeRes = await getNotices();
      const studyRes = await getStudy();

      setNotices(noticeRes.data);
      setStudy(studyRes.data);
    } catch (err) {
      console.log("Error fetching data");
    }
  };

  return (
    <div className="dashboard">

      {/* SIDEBAR */}
      <div className="sidebar">
        <h2>EduSaarthi</h2>

        <button>Dashboard</button>
        <button>Notices</button>
        <button>Study Material</button>
        <button>Upload PDF</button>
        <button>Chatbot</button>
      </div>

      {/* MAIN */}
      <div className="dashboard-main">

        <h2>Admin Dashboard</h2>

        {/* CARDS (REAL DATA) */}
        <div className="dashboard-cards">
          <div className="card">Notices: {notices.length}</div>
          <div className="card">Study Material: {study.length}</div>
          <div className="card">Uploads: {study.length}</div>
          <div className="card">Users: 50</div>
        </div>

        {/* GRAPH */}
        <div className="graph-box">
          <h3>Activity Overview</h3>

          <div style={{ display: "flex" }}>
            <div className="bar" style={{ height: "90px" }}></div>
            <div className="bar" style={{ height: "140px" }}></div>
            <div className="bar" style={{ height: "70px" }}></div>
            <div className="bar" style={{ height: "120px" }}></div>
          </div>
        </div>

        {/* SHOW DATA LIST (VERY IMPORTANT 🔥) */}

        <div className="graph-box">
          <h3>Recent Notices</h3>
          {notices.map((n, i) => (
            <div key={i} className="card" style={{ marginTop: "10px" }}>
              <b>{n.title}</b>
              <p>{n.content}</p>
            </div>
          ))}
        </div>

        <div className="graph-box">
          <h3>Study Material</h3>
          {study.map((s, i) => (
            <div key={i} className="card" style={{ marginTop: "10px" }}>
              <b>{s.title}</b>
              <p>{s.content}</p>
            </div>
          ))}
        </div>

      </div>
    </div>
  );
};

export default AdminDashboard;
